"use client";

import { useState, useRef, useEffect } from "react";
import { MousePointerClick } from "lucide-react";

interface InvestorDocPreviewProps {
  src: string;
  title: string;
}

export function InvestorDocPreview({ src, title }: InvestorDocPreviewProps) {
  const [isInteractive, setIsInteractive] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  // Re-lock the iframe when user clicks outside
  useEffect(() => {
    if (!isInteractive) return;

    function handleClickOutside(e: MouseEvent) {
      if (
        containerRef.current &&
        !containerRef.current.contains(e.target as Node)
      ) {
        setIsInteractive(false);
      }
    }

    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, [isInteractive]);

  return (
    <div ref={containerRef} className="relative">
      {/* Click-to-interact overlay, only shown when iframe is locked */}
      {!isInteractive && (
        <button
          onClick={() => setIsInteractive(true)}
          suppressHydrationWarning
          className="absolute inset-0 z-10 flex items-end justify-center pb-8 bg-transparent cursor-pointer group"
          aria-label="Click to interact with document"
        >
          <span className="flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-full bg-background/90 backdrop-blur-sm border border-border shadow-lg text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity duration-200">
            <MousePointerClick className="w-4 h-4" />
            Click to interact with document
          </span>
        </button>
      )}

      <iframe
        src={src}
        title={title}
        className="w-full border-0 block"
        style={{
          height: "2600px",
          pointerEvents: isInteractive ? "auto" : "none",
        }}
        allow="fullscreen"
      />
    </div>
  );
}
